Use this API to create a Product in Anchanto WMS.

<b>Copy & Paste the JSON below in the Request Body:</b>
<pre>
{
  \"product\": {
    \"name\": \"Wireless Mouse\",
    \"sku\": \"MOUSE-001\",
    \"storage_type\": \"standard\",
    \"base_uom_code\": \"PCS\",
    \"product_type\": \"product\",
    \"product_sales_informations_attributes\": [
      {
        \"currency_code\": \"USD\",
        \"selling_price\": 25.00,
        \"cost_price\": 15.00,
        \"retail_price\": 30.00
      }
    ],
    \"product_dimensions_attributes\": [
      {
        \"length_cm\": 10,
        \"width_cm\": 5,
        \"height_cm\": 3,
        \"weight_gm\": 150,
        \"no_of_units\": 1
      }
    ],
    \"product_localizations_attributes\": [
      {
        \"country_iso\": \"US\",
        \"name\": \"Wireless Mouse\",
        \"mark_as_default\": true
      }
    ]
  }
}
</pre>

